<script setup lang="ts">
import {computed,ref,reactive} from 'vue'
import RecordPage from '../../components/RecordPage.vue'
import type {Definition,Row} from '../../shared/records'
import {http} from '../../api/http'
const extra=ref(''),selected=ref<Row|null>(null),entry=reactive<Row>({}),error=ref(''),calendar=ref<Row[]>([]),saving=ref(false)
const definition:Definition={title:'服务网点',endpoint:'/sites',detail:'/site-settings',columns:[['name','网点'],['address','地址'],['phone','电话'],['businessStatus','营业状态']],fields:[{key:'name',label:'网点名称'},{key:'address',label:'地址'},{key:'phone',label:'电话'},{key:'serviceArea',label:'服务范围',type:'textarea'},{key:'managerUserId',label:'负责人账号编号',type:'number'},{key:'openingHours',label:'营业时间说明'},{key:'lunchTime',label:'午餐开餐时间',initial:'11:30'},{key:'dinnerTime',label:'晚餐开餐时间',initial:'17:30'},{key:'enabledMeals',label:'开放餐次',type:'multi',options:[{value:'LUNCH',label:'午餐'},{value:'DINNER',label:'晚餐'}],initial:['LUNCH','DINNER']}]}
async function openExtra(row:Row,type:string){selected.value=row;extra.value=type;error.value='';entry.date='';entry.mealType='LUNCH';entry.reason='';if(type==='calendar')try{calendar.value=await http.get(`/sites/${row.id}/closed-dates`)}catch(e){error.value=(e as Error).message}}
async function saveExtra(){if(saving.value)return;saving.value=true;try{{const dates=calendar.value.map(v=>({date:v.closedDate,mealType:v.mealType,reason:v.reason}));if(entry.date)dates.push({date:entry.date,mealType:entry.mealType,reason:entry.reason});await http.put(`/sites/${selected.value!.id}/closed-dates`,{dates})}extra.value=''}catch(e){error.value=(e as Error).message}finally{saving.value=false}}

</script>
<template><div><RecordPage :definition="definition"><template #actions="{row,action}"><el-button link @click="action('PATCH',`/sites/${row.id}/status`,{status:row.businessStatus==='OPEN'?'CLOSED':'OPEN'})">{{row.businessStatus==='OPEN'?'停用':'启用'}}</el-button><el-button link @click="openExtra(row,'calendar')">停餐日历</el-button></template></RecordPage> <el-dialog :model-value="!!extra" title="停餐日历" width="min(600px,94vw)" @close="extra=''">
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="form-stack" @submit.prevent="saveExtra"><template v-if="extra==='calendar'"><div v-for="(day,index) in calendar" :key="index">{{day.closedDate}} {{day.mealType}} {{day.reason}} <el-button link type="danger" @click="calendar.splice(index,1)">移除</el-button></div><label for="closed-date">停餐日期</label><el-input id="closed-date" v-model="entry.date" type="date"/><el-select v-model="entry.mealType" aria-label="停餐餐次"><el-option value="LUNCH" label="午餐"/><el-option value="DINNER" label="晚餐"/></el-select><label for="closed-reason">原因</label><el-input id="closed-reason" v-model="entry.reason"/></template><el-button native-type="submit" type="primary" :loading="saving">保存</el-button></form></el-dialog></div></template>
